def render(a):
 aid,title,desc,color,parts=a; minz=min(q[4] for q in parts); hb=any(q[0]=='b' for q in parts); hc=any(q[0]=='c' for q in parts)
 out=['// SPDX-License-Identifier: CC0-1.0','// Original low-poly water-treatment scene prop, millimetres, Z up, base at z = 0.','', 'meta({',f'  name: {json.dumps(aid)},',"  license: 'CC0-1.0',",f'  title: {json.dumps(title)},',f'  description: {json.dumps(desc+" Knobs: overall scale and asset color.")},',"  tags: ['water treatment', 'water utility', 'infrastructure', 'low poly', 'scene prop'],","  kit: 'water-treatment',","  category: 'prop',","  origin: 'base',","  compat: ['water-treatment', 'utility', 'industrial', 'scene'],",'  triangleBudget: 2200,','});','',"const scale = param('scale', 1, { min: 0.7, max: 1.3, step: 0.05, label: 'Overall scale' });",f"const color = param('color', {json.dumps(color)}, {{ label: 'Asset color' }});"]
 if hb: out.append('const b=(x:number,y:number,z:number,w:number,d:number,h:number)=>box(w,d,h,true).translate(x,y,z+h/2).scale(scale);')
 if hc: out.append('const c=(x:number,y:number,z:number,h:number,r:number,n=10)=>cylinder(h,r,n).translate(x,y,z).scale(scale);')
 out+=['',f'const p=assembly({json.dumps(aid)});']
 for q in parts:
  if q[0]=='b': _,n,x,y,z,w,d,h=q;out.append(f'p.part({json.dumps(n)},b({x},{y},{z-minz},{w},{d},{h}).color(color));')
  else: _,n,x,y,z,h,r,nseg=q;out.append(f'p.part({json.dumps(n)},c({x},{y},{z-minz},{h},{r},{nseg}).color(color));')
 out+=['','return p.model();',''];return '\n'.join(out)
for a in ASSETS:(KIT/f'{a[0]}.kcad.ts').write_text(render(a))
(KIT/'kit.json').write_text(json.dumps({'title':'Water treatment','description':'Original low-poly water-treatment and wastewater plant props for intake, filtration, disinfection, pumping, monitoring, and solids handling.'},indent=2)+'\n')
